"Consultez si les symptômes (bouffées de chaleur, sommeil, humeur) pèsent sur votre quotidien : des solutions existent, dont le traitement hormonal à discuter avec votre médecin.": {
"en": "See a doctor if symptoms (hot flushes, sleep, mood) weigh on your daily life: solutions exist, including hormone therapy, to discuss with your doctor.",
"es": "Consulta si los síntomas (sofocos, sueño, estado de ánimo) afectan a tu día a día: existen soluciones, entre ellas el tratamiento hormonal, que puedes hablar con tu médico.",
"pt": "Procure um médico se os sintomas (ondas de calor, sono, humor) pesarem no seu dia a dia: existem soluções, incluindo a terapia hormonal, para conversar com o seu médico.",
"de": "Sprich mit deiner Ärztin oder deinem Arzt, wenn Beschwerden (Hitzewallungen, Schlaf, Stimmung) deinen Alltag belasten: Es gibt Lösungen, darunter eine Hormontherapie.",
"it": "Consulta un medico se i sintomi (vampate, sonno, umore) pesano sulla tua quotidianità: esistono soluzioni, tra cui la terapia ormonale, da valutare con il tuo medico."
},
