"Dans les applications iPhone et Android, vous profitez de 3 jours gratuits avec un accès complet à votre formule. Aucun paiement pendant l’essai. L’abonnement démarre ensuite, sauf si vous annulez au moins 24 h avant la fin. Nous vous envoyons un rappel avant.": {
"en": "In the iPhone and Android apps, you get 3 free days with full access to your plan. Nothing is charged during the trial. Your subscription then starts unless you cancel at least 24 hours before the end. We send you a reminder beforehand.",
"es": "En las apps para iPhone y Android disfrutas de 3 días gratis con acceso completo a tu plan. No se cobra nada durante la prueba. Después empieza la suscripción, salvo que canceles al menos 24 h antes del final. Te enviamos un recordatorio antes.",
"pt": "Nos apps para iPhone e Android, você tem 3 dias grátis com acesso completo ao seu plano. Nada é cobrado durante o teste. Depois a assinatura começa, a menos que você cancele pelo menos 24 h antes do fim. Enviamos um lembrete antes.",
"de": "In der iPhone- und Android-App hast du 3 Tage gratis mit vollem Zugriff auf dein Abo. Während der Testphase wird nichts berechnet. Danach beginnt das Abo, es sei denn, du kündigst mindestens 24 Stunden vor Ende. Wir erinnern dich vorher.",
"it": "Nelle app per iPhone e Android hai 3 giorni gratis con accesso completo al tuo piano. Durante la prova non paghi nulla. Poi parte l’abbonamento, a meno che tu non annulli almeno 24 ore prima della fine. Ti mandiamo un promemoria prima."
},
