"Descendez en 2 à 3 secondes.": {
"en": "Lower over 2 to 3 seconds.",
"es": "Baja en 2 o 3 segundos.",
"pt": "Desça em 2 a 3 segundos.",
"de": "In 2 bis 3 Sekunden absenken.",
"it": "Scendi in 2-3 secondi."
},
"Descendez en gardant les talons au sol.": {
"en": "Lower while keeping your heels on the floor.",
"es": "Baja manteniendo los talones en el suelo.",
"pt": "Desça mantendo os calcanhares no chão.",
"de": "Geh nach unten, die Fersen bleiben am Boden.",
"it": "Scendi tenendo i talloni a terra."
},
"Descendez en poussant les fesses en arrière, genoux dans l’axe des pieds.": {
"en": "Lower by pushing your hips back, knees in line with your feet.",
"es": "Baja llevando la cadera hacia atrás, con las rodillas alineadas con los pies.",
"pt": "Desça levando o quadril para trás, joelhos alinhados com os pés.",
"de": "Geh nach unten, indem du den Po nach hinten schiebst, Knie in Linie mit den Füßen.",
"it": "Scendi spingendo i glutei indietro, ginocchia in linea con i piedi."
},
"Descendez jusqu’à ce que les bras soient parallèles au sol.": {
"en": "Lower until your upper arms are parallel to the floor.",
"es": "Baja hasta que los brazos queden paralelos al suelo.",
"pt": "Desça até os braços ficarem paralelos ao chão.",
"de": "Senke dich, bis die Oberarme parallel zum Boden sind.",
"it": "Scendi finché le braccia sono parallele al pavimento."
},
"Descendez jusqu’à environ 90° aux genoux.": {
"en": "Lower until your knees are at about 90°.",
"es": "Baja hasta unos 90° de flexión de rodillas.",
"pt": "Desça até os joelhos ficarem a cerca de 90°.",
"de": "Senke bis etwa 90° im Knie ab.",
"it": "Scendi fino a circa 90° alle ginocchia."
},
"Descendez la barre au bas des pectoraux, coudes à environ 45° du corps.": {
"en": "Lower the bar to the bottom of your chest, elbows at about 45° from your body.",
"es": "Baja la barra a la parte baja del pecho, con los codos a unos 45° del cuerpo.",
"pt": "Desça a barra até a parte de baixo do peito, cotovelos a cerca de 45° do corpo.",
"de": "Senke die Stange zum unteren Brustbereich, Ellbogen etwa 45° vom Körper.",
"it": "Porta il bilanciere alla parte bassa del petto, gomiti a circa 45° dal corpo."
},
"Descendez la barre le long des jambes en poussant les hanches en arrière.": {
"en": "Lower the bar along your legs while pushing your hips back.",
"es": "Baja la barra pegada a las piernas llevando la cadera hacia atrás.",
"pt": "Desça a barra rente às pernas levando o quadril para trás.",
"de": "Führe die Stange an den Beinen entlang nach unten und schiebe die Hüfte nach hinten.",
"it": "Fai scendere il bilanciere lungo le gambe spingendo le anche indietro."
},
"Descendez lentement jusqu’à sentir l’étirement des pectoraux.": {
"en": "Lower slowly until you feel a stretch in your chest.",
"es": "Baja despacio hasta sentir el estiramiento en el pecho.",
"pt": "Desça devagar até sentir o alongamento no peito.",
"de": "Langsam absenken, bis du die Dehnung in der Brust spürst.",
"it": "Scendi lentamente fino a sentire l’allungamento del petto."
},
"Descendez verticalement.": {
"en": "Lower straight down.",
"es": "Baja en vertical.",
"pt": "Desça na vertical.",
"de": "Senkrecht nach unten gehen.",
"it": "Scendi in verticale."
},
