"La baisse progressive des œstrogènes modifie la façon dont le corps stocke les graisses : elles se placent plus volontiers autour de la taille. Ce n’est ni un manque de volonté ni une fatalité.": {
"en": "The gradual drop in oestrogen changes how your body stores fat: it settles more readily around the waist. It’s neither a lack of willpower nor inevitable.",
"es": "La bajada progresiva de estrógenos cambia la forma en que el cuerpo almacena la grasa: tiende a acumularse alrededor de la cintura. No es falta de voluntad ni una fatalidad.",
"pt": "A queda gradual do estrogênio muda a forma como o corpo armazena gordura: ela passa a se acumular mais na cintura. Não é falta de força de vontade nem algo inevitável.",
"de": "Der allmähliche Östrogenabfall verändert, wie der Körper Fett speichert: Es lagert sich eher um die Taille an. Das ist weder mangelnde Willenskraft noch Schicksal.",
"it": "Il calo progressivo degli estrogeni cambia il modo in cui il corpo accumula grasso: tende a depositarsi intorno al girovita. Non è mancanza di volontà né una condanna."
},
"La nouvelle saison": {
"en": "The new season",
"es": "La nueva temporada",
"pt": "A nova estação",
"de": "Die neue Saison",
"it": "La nuova stagione"
},
"La régularité": {
"en": "Consistency",
"es": "La constancia",
"pt": "A constância",
"de": "Die Regelmäßigkeit",
"it": "La costanza"
},
"La vitamine D vient surtout du soleil et de quelques aliments (poissons gras, œufs). Votre médecin peut vérifier votre taux.": {
"en": "Vitamin D comes mainly from sunlight and a few foods (oily fish, eggs). Your doctor can check your levels.",
"es": "La vitamina D procede sobre todo del sol y de algunos alimentos (pescado azul, huevos). Tu médico puede comprobar tus niveles.",
"pt": "A vitamina D vem principalmente do sol e de alguns alimentos (peixes gordos, ovos). Seu médico pode verificar seus níveis.",
"de": "Vitamin D stammt vor allem aus Sonnenlicht und einigen Lebensmitteln (fetter Fisch, Eier). Deine Ärztin oder dein Arzt kann deinen Wert prüfen.",
"it": "La vitamina D arriva soprattutto dal sole e da alcuni alimenti (pesce grasso, uova). Il medico può controllare i tuoi livelli."
},
"Le but de la semaine 1 n’est pas d’être parfait, mais de voir clair.": {
"en": "The aim of week 1 isn’t to be perfect, but to see clearly.",
"es": "El objetivo de la semana 1 no es ser perfecto, sino ver con claridad.",
"pt": "O objetivo da semana 1 não é ser perfeito, mas enxergar com clareza.",
"de": "Ziel der ersten Woche ist nicht Perfektion, sondern Klarheit.",
"it": "L’obiettivo della settimana 1 non è essere perfetti, ma vederci chiaro."
},
