"NutriPilot ajuste vos calories et vos protéines à votre entraînement pour progresser sans prendre de gras inutile.": {
"en": "NutriPilot adjusts your calories and protein to your training so you progress without gaining unnecessary fat.",
"es": "NutriPilot ajusta tus calorías y proteínas a tu entrenamiento para progresar sin ganar grasa innecesaria.",
"pt": "O NutriPilot ajusta suas calorias e proteínas ao seu treino para você evoluir sem ganhar gordura desnecessária.",
"de": "NutriPilot passt Kalorien und Eiweiß an dein Training an, damit du Fortschritte machst, ohne unnötig Fett zuzulegen.",
"it": "NutriPilot adatta calorie e proteine al tuo allenamento per progredire senza prendere grasso inutile."
},
"NutriPilot ne remplace pas un médecin ou un diététicien. En cas de grossesse, de maladie, de traitement ou de trouble du comportement alimentaire, demandez d’abord l’avis d’un professionnel. L’application est réservée aux adultes.": {
"en": "NutriPilot doesn’t replace a doctor or dietitian. If you’re pregnant, ill, on medication or have an eating disorder, ask a professional first. The app is for adults only.",
"es": "NutriPilot no sustituye a un médico ni a un dietista. En caso de embarazo, enfermedad, tratamiento o trastorno de la conducta alimentaria, consulta antes a un profesional. La app está reservada a adultos.",
"pt": "O NutriPilot não substitui um médico ou nutricionista. Em caso de gravidez, doença, tratamento ou transtorno alimentar, consulte um profissional antes. O app é exclusivo para adultos.",
"de": "NutriPilot ersetzt keine Ärztin, keinen Arzt und keine Ernährungsberatung. Bei Schwangerschaft, Krankheit, Medikamenten oder Essstörungen frag zuerst eine Fachperson. Die App ist nur für Erwachsene.",
"it": "NutriPilot non sostituisce un medico o un dietista. In caso di gravidanza, malattia, terapia o disturbo alimentare, chiedi prima a un professionista. L’app è riservata agli adulti."
},
"NutriPilot ne vous demandera pas de tout supprimer. Il calcule un rythme qui respecte votre énergie, votre vie sociale et le plaisir de manger, puis vous guide repas après repas.": {
"en": "NutriPilot won’t ask you to cut everything out. It calculates a pace that respects your energy, your social life and the pleasure of eating, then guides you meal after meal.",
"es": "NutriPilot no te pedirá que lo elimines todo. Calcula un ritmo que respeta tu energía, tu vida social y el placer de comer, y te guía comida a comida.",
"pt": "O NutriPilot não vai pedir que você corte tudo. Ele calcula um ritmo que respeita sua energia, sua vida social e o prazer de comer, e guia você refeição após refeição.",
"de": "NutriPilot verlangt nicht, dass du auf alles verzichtest. Es berechnet ein Tempo, das deine Energie, dein Sozialleben und den Genuss respektiert, und begleitet dich Mahlzeit für Mahlzeit.",
"it": "NutriPilot non ti chiederà di eliminare tutto. Calcola un ritmo che rispetta la tua energia, la tua vita sociale e il piacere di mangiare, e ti guida pasto dopo pasto."
},
"NutriPilot vous aide au quotidien, mais ne remplace pas un suivi médical.": {
"en": "NutriPilot helps you day to day, but it doesn’t replace medical care.",
"es": "NutriPilot te ayuda en el día a día, pero no sustituye un seguimiento médico.",
"pt": "O NutriPilot ajuda no dia a dia, mas não substitui o acompanhamento médico.",
"de": "NutriPilot hilft dir im Alltag, ersetzt aber keine ärztliche Betreuung.",
"it": "NutriPilot ti aiuta ogni giorno, ma non sostituisce un controllo medico."
},
