"Prenez votre assiette en photo, écrivez ou dictez ce que vous mangez, scannez un code-barres ou une étiquette. NutriPilot estime calories, protéines, glucides, lipides, fibres et sel, et vous corrigez les grammes en un geste.": {
"en": "Take a photo of your plate, type or dictate what you eat, or scan a barcode or label. NutriPilot estimates calories, protein, carbs, fat, fibre and salt, and you adjust the grams in one tap.",
"es": "Haz una foto de tu plato, escribe o dicta lo que comes, o escanea un código de barras o una etiqueta. NutriPilot estima calorías, proteínas, hidratos, grasas, fibra y sal, y tú ajustas los gramos en un gesto.",
"pt": "Tire uma foto do prato, escreva ou dite o que você come, ou escaneie um código de barras ou rótulo. O NutriPilot estima calorias, proteínas, carboidratos, gorduras, fibras e sal, e você ajusta os gramas com um toque.",
"de": "Fotografiere deinen Teller, tippe oder diktiere, was du isst, oder scanne einen Barcode oder ein Etikett. NutriPilot schätzt Kalorien, Eiweiß, Kohlenhydrate, Fett, Ballaststoffe und Salz, und du korrigierst die Gramm mit einem Tipp.",
"it": "Fotografa il piatto, scrivi o detta cosa mangi, oppure scansiona un codice a barre o un’etichetta. NutriPilot stima calorie, proteine, carboidrati, grassi, fibre e sale, e tu correggi i grammi con un tocco."
},
