"Échauffez-vous 5 à 10 minutes avant chaque séance. Choisissez une charge qui vous laisse 1 à 2 répétitions en réserve. Arrêtez en cas de douleur et demandez un avis médical si vous avez un problème de santé.": {
"en": "Warm up for 5 to 10 minutes before each session. Choose a weight that leaves 1 to 2 reps in reserve. Stop if you feel pain and seek medical advice if you have a health condition.",
"es": "Calienta 5 a 10 minutos antes de cada sesión. Elige un peso que te deje 1 o 2 repeticiones en reserva. Para si sientes dolor y consulta a un médico si tienes un problema de salud.",
"pt": "Aqueça de 5 a 10 minutos antes de cada treino. Escolha uma carga que deixe 1 a 2 repetições de reserva. Pare se sentir dor e procure orientação médica se tiver algum problema de saúde.",
"de": "Wärme dich vor jeder Einheit 5 bis 10 Minuten auf. Wähle ein Gewicht, bei dem 1 bis 2 Wiederholungen in Reserve bleiben. Hör bei Schmerzen auf und hol ärztlichen Rat ein, wenn du gesundheitliche Probleme hast.",
"it": "Riscaldati 5-10 minuti prima di ogni sessione. Scegli un carico che ti lasci 1-2 ripetizioni di riserva. Fermati in caso di dolore e chiedi un parere medico se hai problemi di salute."
},
