"Eau, sel, digestion, sommeil et cycle peuvent déplacer le poids sans refléter une variation équivalente de masse grasse.": {
"en": "Water, salt, digestion, sleep and your cycle can shift your weight without reflecting an equivalent change in body fat.",
"es": "El agua, la sal, la digestión, el sueño y el ciclo pueden mover el peso sin reflejar un cambio equivalente de grasa.",
"pt": "Água, sal, digestão, sono e ciclo menstrual podem alterar o peso sem refletir uma mudança equivalente de gordura.",
"de": "Wasser, Salz, Verdauung, Schlaf und Zyklus können das Gewicht verschieben, ohne dass sich der Fettanteil entsprechend ändert.",
"it": "Acqua, sale, digestione, sonno e ciclo possono far variare il peso senza riflettere una variazione equivalente di massa grassa."
},
