"de": "Wähle Tage, Ort, Stil und wie oft pro Woche jede Zone trainiert wird. NutriPilot baut die Einheiten.",
"it": "Scegli giorni, luogo, stile e quante volte a settimana allenare ogni zona. NutriPilot crea le sedute."
